    super({ readableObjectMode: false, ...opts });
    this.fields = fields;
    this.decoder = new StringDecoder('utf8');
    this.state = 'fieldStart'; // fieldStart | unquoted | quoted | quoteInQuoted
    this.field = [];
    this.row = [];
    this.header = null;
    this.indices = null;
    this.skipLF = false;
    this.headerWritten = false;
