#!/usr/bin/env node
'use strict';

const { Transform } = require('node:stream');
const { StringDecoder } = require('node:string_decoder');

/**
 * Escape a single CSV value per RFC 4180:
 * quote if it contains a comma, quote, CR or LF; double any embedded quotes.
 */
function csvEscape(value) {
  const s = String(value);
  if (/[",\r\n]/.test(s)) return '"' + s.replace(/"/g, '""') + '"';
  return s;
}

/**
 * Streaming CSV column selector.
 *
 * Implements an incremental RFC 4180 parser as a Transform stream:
 *   - quoted fields may contain commas, doubled quotes ("") and newlines
 *   - records may be terminated by \n, \r\n or \r
 *   - a final record without a trailing newline is still emitted
 *
 * Memory usage is bounded by the size of a single logical record (a quoted
 * field may legitimately span chunks), never by total input size.
 */
class CsvPickStream extends Transform {
  /**
   * @param {string[]} fields header names to select, in output order
   */
  constructor(fields) {
    super();
    if (!Array.isArray(fields) || fields.length === 0) {
      throw new TypeError('fields must be a non-empty array of header names');
    }
    this.requestedFields = fields;

    this.decoder = new StringDecoder('utf8'); // safe across UTF-8 chunk splits

    // Parser state machine
    this.state = 'fieldStart'; // fieldStart | unquoted | quoted | quoteInQuoted
    this.fieldParts = [];
    this.row = [];
    this.skipLF = false; // swallow \n right after \r (CRLF)

    this.header = null;
    this.indices = null;
    this.headerEmitted = false;
  }

  _transform(chunk, _enc, cb) {
    try {
      this.feed(this.decoder.write(chunk));
      cb();
    } catch (err) {
      cb(err);
    }
  }

  _flush(cb) {
    try {
      this.feed(this.decoder.end());
      this.skipLF = false;
      // Emit a final unterminated record, but not if the stream ended exactly
      // on a record boundary (or the input was completely empty).
      if (this.state !== 'fieldStart' || this.fieldParts.length > 0 || this.row.length > 0) {
        this.endField();
        this.emitRow();
      }
      cb();
    } catch (err) {
      cb(err);
    }
  }

  feed(s) {
    for (let i = 0; i < s.length; i++) {
      const c = s[i];

      if (this.skipLF) {
        this.skipLF = false;
        if (c === '\n') continue; // CRLF: the \r already ended the record
      }

      switch (this.state) {
        case 'fieldStart':
          if (c === '"') {
            this.state = 'quoted';
          } else if (c === ',') {
            this.endField();
          } else if (c === '\n') {
            this.endField();
            this.emitRow();
          } else if (c === '\r') {
            this.endField();
            this.emitRow();
            this.skipLF = true;
          } else {
            this.fieldParts.push(c);
            this.state = 'unquoted';
          }
          break;

        case 'unquoted':
          if (c === ',') {
            this.endField();
          } else if (c === '\n') {
            this.endField();
            this.emitRow();
          } else if (c === '\r') {
            this.endField();
            this.emitRow();
            this.skipLF = true;
          } else {
            this.fieldParts.push(c);
          }
          break;

        case 'quoted':
          if (c === '"') {
            this.state = 'quoteInQuoted';
          } else {
            // commas and newlines are literal inside quotes
            this.fieldParts.push(c);
          }
          break;

        case 'quoteInQuoted':
          if (c === '"') {
            this.fieldParts.push('"'); // doubled quote -> literal quote
            this.state = 'quoted';
          } else if (c === ',') {
            this.endField();
          } else if (c === '\n') {
            this.endField();
            this.emitRow();
          } else if (c === '\r') {
            this.endField();
            this.emitRow();
            this.skipLF = true;
          } else {
            // Lenient: stray text after a closing quote is treated as data.
            this.fieldParts.push(c);
            this.state = 'unquoted';
          }
          break;
      }
    }
  }

  endField() {
    this.row.push(this.fieldParts.join(''));
    this.fieldParts = [];
    this.state = 'fieldStart';
  }

  emitRow() {
    const record = this.row;
    this.row = [];

    if (!this.headerEmitted) {
      this.header = record;
      this.indices = this.requestedFields.map((name) => {
        const idx = record.indexOf(name);
        if (idx === -1) {
          throw new Error(
            `column not found in header: ${JSON.stringify(name)} ` +
              `(header: ${record.map((h) => JSON.stringify(h)).join(', ')})`
          );
        }
        return idx;
      });
      this.headerEmitted = true;
      this.push(this.requestedFields.map(csvEscape).join(',') + '\n');
      return;
    }

    let out = '';
    for (let i = 0; i < this.indices.length; i++) {
      if (i > 0) out += ',';
      out += csvEscape(record[this.indices[i]] ?? '');
    }
    this.push(out + '\n');
  }
}

function usage() {
  process.stderr.write(
    'usage: node csvpick.js --fields name,email [--fields=x,y]\n' +
      'reads CSV (with header row) on stdin, writes selected columns to stdout\n'
  );
}

function parseArgv(argv) {
  let fields = null;
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--fields') {
      if (i + 1 >= argv.length) throw new Error('--fields requires a value');
      fields = argv[++i];
    } else if (a.startsWith('--fields=')) {
      fields = a.slice('--fields='.length);
    } else if (a === '-h' || a === '--help') {
      usage();
      process.exit(0);
    } else {
      throw new Error(`unknown argument: ${a}`);
    }
  }
  if (!fields) {
    usage();
    throw new Error('missing required --fields option');
  }
  return fields
    .split(',')
    .map((f) => f.trim())
    .filter((f) => f.length > 0);
}

module.exports = { CsvPickStream, csvEscape };

if (require.main === module) {
  let fields;
  try {
    fields = parseArgv(process.argv.slice(2));
  } catch (err) {
    process.stderr.write(`csvpick: ${err.message}\n`);
    process.exit(2);
  }

  let picker;
  try {
    picker = new CsvPickStream(fields);
  } catch (err) {
    process.stderr.write(`csvpick: ${err.message}\n`);
    process.exit(2);
  }

  process.stdin.pipe(picker).pipe(process.stdout);
  picker.on('error', (err) => {
    process.stderr.write(`csvpick: ${err.message}\n`);
    process.exit(1);
  });
}

