'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const path = require('node:path');
const { CsvPickStream } = require('../csvpick.js');

const SCRIPT = path.join(__dirname, '..', 'csvpick.js');

/** Feed chunks through a CsvPickStream and collect stdout as a string. */
async function run(chunks, fields = ['name', 'email']) {
  const picker = new CsvPickStream(fields);
  const out = [];
  picker.on('data', (d) => out.push(d));
  const done = new Promise((resolve, reject) => {
    picker.on('end', resolve);
    picker.on('error', reject);
  });
  for (const chunk of chunks) {
    if (!picker.write(chunk)) {
      await new Promise((r) => picker.once('drain', r)); // force chunk boundary
    }
  }
  picker.end();
  await done;
  return Buffer.concat(out).toString('utf8');
}

test('simple rows, unquoted fields', async () => {
  const out = await run([Buffer.from('name,email\nann,a@x.io\nbob,b@x.io\n')]);
  assert.equal(out, 'name,email\nann,a@x.io\nbob,b@x.io\n');
});

test('row split across chunk boundary mid-field', async () => {
  const out = await run([Buffer.from('name,email\nal'), Buffer.from('ice,a@x.io\n')]);
  assert.equal(out, 'name,email\nalice,a@x.io\n');
});

test('quoted field containing comma, split inside the quotes', async () => {
  const chunks = [
    Buffer.from('name,email,note\nDoe, Jane,j@x.io,"a,b'),
    Buffer.from(',c"\n'),
  ];
  const out = await run(chunks);
  const lines = out.split('\n');
  assert.equal(lines[0], 'name,email,note');
  // "a,b,c" must be re-quoted on output since it contains commas
  assert.equal(lines[1], '"Doe, Jane",j@x.io,"a,b,c"');
});

test('quoted field with embedded newline, split exactly at the newline', async () => {
  const chunks = [
    Buffer.from('name,email\nann,a@x.io,"line1'),
    Buffer.from('\nline2"\nbob,b@x.io\n'),
  ];
  const out = await run(chunks);
  assert.equal(out, 'name,email\nann,a@x.io,"line1\nline2"\nbob,b@x.io\n');
});

test('doubled quotes inside quoted field, split between the two quotes', async () => {
  const chunks = [
    Buffer.from('name,quote\nann,"she said ""hi'),
    Buffer.from('"" ok"\n'),
  ];
  const out = await run(chunks);
  assert.equal(out, 'name,quote\nann,"she said ""hi"" ok"\n');
});

test('CRLF line endings, CRLF split across chunks', async () => {
  const out = await run([
    Buffer.from('name,email\r\nann,a@x'),
    Buffer.from('.io\r'),
    Buffer.from('\nbob,b@x.io\r\n'),
  ]);
  assert.equal(out, 'name,email\nann,a@x.io\nbob,b@x.io\n');
});

test('field selection reorders columns and picks subset', async () => {
  const csv = 'id,name,email\n1,ann,a@x.io\n2,bob,"b,x"\n';
  const out = await run([Buffer.from(csv)], ['email', 'name']);
  assert.equal(out, 'email,name\na@x.io,ann\n"b,x",bob\n');
});

test('missing trailing newline still emits final row', async () => {
  const out = await run([Buffer.from('name,email\nann,a@x.io')]);
  assert.equal(out, 'name,email\nann,a@x.io\n');
});

