const test = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const path = require('node:path');
const { CsvPickStream } = require('../csvpick.js');

const SCRIPT = path.join(__dirname, '..', 'csvpick.js');

/** Feed chunks through a CsvPickStream and collect stdout as a string. */
async function run(chunks, fields = ['name', 'email']) {
  const picker = new CsvPickStream(fields);
  const out = [];
  picker.on('data', (d) => out.push(d));
  const done = new Promise((resolve, reject) => {
    picker.on('end', resolve);
    picker.on('error', reject);
  });
  for (const chunk of chunks) {
    if (!picker.write(chunk)) {
      await new Promise((r) => picker.once('drain', r)); // force chunk boundary
    }
  }
  picker.end();
  await done;
  return Buffer.concat(out).toString('utf8');
}

